mapper.select:
SELECT shift_id
FROM shift_schedule
WHERE store_staff_id = #{storeStaffId}
  AND work_date = #{workDate}
  AND status = 'CONFIRMED'
LIMIT 1

SELECT r.mod_request_id, r.attendance_id, r.store_id, r.store_staff_id, m.full_name AS staff_name, r.work_date, r.before_clock_in_at, r.before_clock_out_at, r.before_break_minutes, r.requested_clock_in_at, r.requested_clock_out_at, r.requested_break_minutes, r.reason, r.approval_status, r.reject_reason, r.created_at FROM attendance_mod_request r JOIN store_staff ss ON r.store_staff_id = ss.store_staff_id JOIN member m ON ss.member_id = m.member_id WHERE r.store_id = #{storeId}
AND r.approval_status = #{status}
ORDER BY r.mod_request_id DESC

mapper.update:
UPDATE attendance_mod_request
SET approval_status = #{status},
    reviewer_id = #{reviewerId},
    reject_reason = #{rejectReason},
    reviewed_at = #{reviewedAt}
WHERE mod_request_id = #{modRequestId}
